from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(np.float32)
# Estimate horizontal and vertical line structure from rows/cols using gradients and print ranges
l=im.mean(2); dx=np.abs(np.diff(l,axis=1)); dy=np.abs(np.diff(l,axis=0))
# Top/bottom band profiles
for name,a in [('top',dx[:90]),('mid',dx[90:140]),('bot',dx[140:])]:
 p=a.mean(0); peaks=[]
 for x in range(2,254):
  if p[x]>p[x-1] and p[x]>=p[x+1] and p[x]>8: peaks.append((p[x],x))
 print(name, sorted(peaks,reverse=True)[:25])
for name,a in [('left',dy[:,:128]),('right',dy[:,128:])]:
 p=a.mean(1); peaks=[]
 for y in range(2,190):
  if p[y]>p[y-1] and p[y]>=p[y+1] and p[y]>8: peaks.append((p[y],y))
 print(name, sorted(peaks,reverse=True)[:30])
